use tauri::{menu::{Menu, MenuItem},tray::{MouseButton, MouseButtonState, TrayIconBuilder, TrayIconEvent},Emitter, Manager, WebviewUrl, WebviewWindow, WebviewWindowBuilder};
fn show_main_window(app:&tauri::AppHandle){if let Some(window)=app.get_webview_window("main"){let _=window.unminimize();let _=window.show();let _=window.set_focus();}}
#[tauri::command] fn read_backup(path:String)->Result<String,String>{std::fs::read_to_string(path).map_err(|e|e.to_string())}
#[tauri::command] fn write_backup(path:String,payload:String)->Result<(),String>{std::fs::write(path,payload).map_err(|e|e.to_string())}
#[tauri::command] async fn show_main(app:tauri::AppHandle)->Result<(),String>{show_main_window(&app);Ok(())}
#[tauri::command] async fn request_dock(app:tauri::AppHandle,window:WebviewWindow,id:String)->Result<(),String>{show_main_window(&app);app.emit_to("main","request-dock-block",serde_json::json!({"id":id})).map_err(|e|e.to_string())?;window.close().map_err(|e|e.to_string())?;Ok(())}
#[tauri::command] async fn spawn_detached_block(app:tauri::AppHandle,id:String,x:i32,y:i32)->Result<(),String>{let label=format!("block-{}",id.replace(|c:char|!c.is_ascii_alphanumeric(),"-"));if let Some(existing)=app.get_webview_window(&label){existing.show().map_err(|e|e.to_string())?;existing.set_focus().map_err(|e|e.to_string())?;return Ok(())}let url=WebviewUrl::App(format!("index.html?floating={}",id).into());let win=WebviewWindowBuilder::new(&app,label,url).title("Questboard block").inner_size(430.0,340.0).min_inner_size(310.0,220.0).position((x-215) as f64,(y-45) as f64).decorations(false).transparent(true).always_on_top(true).shadow(true).resizable(true).skip_taskbar(false).build().map_err(|e|e.to_string())?;let _=win.set_focus();Ok(())}
#[cfg_attr(mobile,tauri::mobile_entry_point)] pub fn run(){tauri::Builder::default().plugin(tauri_plugin_single_instance::init(|app,_args,_cwd|{show_main_window(app);})).plugin(tauri_plugin_autostart::Builder::new().arg("--autostart").build()).plugin(tauri_plugin_global_shortcut::Builder::new().build()).plugin(tauri_plugin_dialog::init()).plugin(tauri_plugin_fs::init()).plugin(tauri_plugin_shell::init()).plugin(tauri_plugin_sql::Builder::default().build()).setup(|app|{let show=MenuItem::with_id(app,"show","Open Questboard",true,None::<&str>)?;let quit=MenuItem::with_id(app,"quit","Quit",true,None::<&str>)?;let menu=Menu::with_items(app,&[&show,&quit])?;let mut builder=TrayIconBuilder::new().tooltip("Questboard").menu(&menu).show_menu_on_left_click(false).on_menu_event(|app,event|match event.id().as_ref(){"show"=>show_main_window(app),"quit"=>app.exit(0),_=>{}}).on_tray_icon_event(|tray,event|{if let TrayIconEvent::Click{button:MouseButton::Left,button_state:MouseButtonState::Up,..}=event{show_main_window(tray.app_handle());}});if let Some(icon)=app.default_window_icon(){builder=builder.icon(icon.clone());}let _tray=builder.build(app)?;if std::env::args().any(|arg|arg=="--autostart"){if let Some(window)=app.get_webview_window("main"){let _=window.hide();}}Ok(())}).on_window_event(|window,event|{if window.label()=="main"{if let tauri::WindowEvent::CloseRequested{api,..}=event{api.prevent_close();let _=window.hide();}}}).invoke_handler(tauri::generate_handler![spawn_detached_block,request_dock,show_main,write_backup,read_backup]).run(tauri::generate_context!()).expect("error while running Questboard");}
